import * as THREE from 'three';
import {mergeGeometries} from 'three/addons/utils/BufferGeometryUtils.js';
import {SKY_MOODS} from '../world/time-of-day.js';
import {SKY_VERTEX,SKY_FRAGMENT,WATER_VERTEX,WATER_FRAGMENT,BOAT_VERTEX,BOAT_FRAGMENT} from './ocean-shaders.js';
const PALETTES={morning:['#6499bc','#dde5df','#fff1d5','#f4f1e9','#a7b8c3','#285f75','#b8ced1'],day:['#548bb7','#d7e5e8','#fff0d3','#f4f3ed','#a3b5c4','#245b72','#afc9ce'],evening:['#675f87','#e6bca0','#ffd09e','#ddc6c3','#887f9a','#304e70','#b6aebd'],night:['#101f36','#667f99','#e3e9d9','#8394aa','#334861','#142b43','#506e88']};
const safe=(v,f)=>Number.isFinite(v)&&Math.abs(v)<10000?v:f;
function nearestMood(color){if(!color?.isColor)return'day';let best='day',distance=Infinity;for(const[id,p]of Object.entries(SKY_MOODS)){const c=new THREE.Color(p.water),d=(color.r-c.r)**2+(color.g-c.g)**2+(color.b-c.b)**2;if(d<distance){best=id;distance=d;}}return best;}
function boatGeometry(){const pieces=[];function add(g,color,position,scale=[1,1,1],rotation=null){if(rotation)g.rotateZ(rotation);g.scale(...scale);g.translate(...position);const b=g.index?g.toNonIndexed():g;const colors=new Float32Array(b.attributes.position.count*3),c=new THREE.Color(color);for(let i=0;i<b.attributes.position.count;i++){const ny=b.attributes.normal?.getY(i)??.6,nz=b.attributes.normal?.getZ(i)??.6,shade=.76+.24*Math.max(0,ny*.6+nz*.4);colors[i*3]=c.r*shade;colors[i*3+1]=c.g*shade;colors[i*3+2]=c.b*shade;}b.deleteAttribute('normal');b.deleteAttribute('uv');b.setAttribute('color',new THREE.BufferAttribute(colors,3));pieces.push(b);if(b!==g)g.dispose();}
 add(new THREE.SphereGeometry(1,12,4),'#536d73',[0,.08,0],[.64,.095,.17]);add(new THREE.BoxGeometry(1,1,1),'#b9b8a1',[0,.145,0],[.80,.035,.22]);add(new THREE.CylinderGeometry(.012,.014,.69,5,1),'#827e6d',[-.06,.48,0]);
 const sail=(points,color)=>{const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(points,3));g.computeVertexNormals();add(g,color,[0,0,0]);};sail([-.06,.81,.006,.38,.20,.006,-.06,.20,.006],'#e6e5d6');sail([-.08,.69,-.008,-.42,.20,-.008,-.08,.20,-.008],'#c5d0c9');
 const result=mergeGeometries(pieces);pieces.forEach(p=>p.dispose());return result;
}
/** Owned procedural vista. Preserves the existing root/update/snapshot/dispose
 * contract and frame-scoped leases. No world mutations, textures or RTTs. */
export function createOceanView({camera=null,centerX=0,coastZ=41.1,waterY=-.35,mood=null,waterColor=null}={}){
 const root=new THREE.Group();root.name='plaza.ocean-view';
 const uniforms={uResolution:{value:new THREE.Vector2(390,844)},uTime:{value:0},uHorizon:{value:.56},uNight:{value:0},uEvening:{value:0},uDetail:{value:1},uSunUV:{value:new THREE.Vector2(.69,.80)},uZenith:{value:new THREE.Color()},uHaze:{value:new THREE.Color()},uSunColor:{value:new THREE.Color()},uCloudLight:{value:new THREE.Color()},uCloudShade:{value:new THREE.Color()},uDeepWater:{value:new THREE.Color()},uFarWater:{value:new THREE.Color()},uViewProjection:{value:new THREE.Matrix4()},uModel:{value:new THREE.Matrix4()},uEye:{value:new THREE.Vector3()},uViewDirection:{value:new THREE.Vector3(0,0,1)},uBoatXZ:{value:new THREE.Vector2()},uCoast:{value:coastZ}};
 const make=(vertexShader,fragmentShader,options={})=>new THREE.RawShaderMaterial({glslVersion:THREE.GLSL3,vertexShader,fragmentShader,uniforms,toneMapped:false,...options});
 const sky=new THREE.Mesh(new THREE.PlaneGeometry(2,2),make(SKY_VERTEX,SKY_FRAGMENT,{depthWrite:false}));sky.name='plaza.ocean.sky';sky.frustumCulled=false;root.add(sky);
 const waterGeometry=new THREE.BufferGeometry();waterGeometry.setAttribute('position',new THREE.Float32BufferAttribute(new Float32Array(12),3));waterGeometry.setIndex([0,1,2,0,2,3]);const water=new THREE.Mesh(waterGeometry,make(WATER_VERTEX,WATER_FRAGMENT,{side:THREE.DoubleSide}));water.name='plaza.ocean.water';water.frustumCulled=false;root.add(water);
 const boat=new THREE.Mesh(boatGeometry(),make(BOAT_VERTEX,BOAT_FRAGMENT,{side:THREE.DoubleSide}));boat.name='plaza.ocean.boat';boat.scale.setScalar(.40);boat.frustumCulled=false;root.add(boat);
 let alive=true,time=0,sourceCamera=camera,x=safe(centerX,0),coast=safe(coastZ,41.1),y=safe(waterY,-.35),phase=PALETTES[mood]?mood:nearestMood(waterColor),lastPalette='',width=30;
 const view=new THREE.Matrix4(),world=new THREE.Matrix4(),one=new THREE.Vector3(1,1,1),point=new THREE.Vector3(),forward=uniforms.uViewDirection.value;
 function tint(){if(lastPalette===phase)return;lastPalette=phase;for(const[key,i]of[['uZenith',0],['uHaze',1],['uSunColor',2],['uCloudLight',3],['uCloudShade',4],['uDeepWater',5],['uFarWater',6]])uniforms[key].value.set(PALETTES[phase][i]);uniforms.uNight.value=phase==='night'?1:0;uniforms.uEvening.value=phase==='evening'?1:0;}
 function poseBoat(){boat.position.set(x+1.65+1.30*Math.sin(time*.009),y+.027+.013*Math.sin(time*.55+.8),coast+186+.4*Math.sin(time*.025));boat.rotation.set(.014*Math.sin(time*.43),.10+.03*Math.sin(time*.025),.022*Math.sin(time*.55+.8));boat.updateMatrix();uniforms.uModel.value.copy(boat.matrix);uniforms.uBoatXZ.value.set(boat.position.x,boat.position.z);}
 function waterExtent(){const a=waterGeometry.attributes.position,w=width*.5,z0=coast+.7,z1=coast+260;a.setXYZ(0,x-w,y+.013,z0);a.setXYZ(1,x+w,y+.013,z0);a.setXYZ(2,x+w,y+.013,z1);a.setXYZ(3,x-w,y+.013,z1);a.needsUpdate=true;uniforms.uCoast.value=coast;}
 function cameraFrame(c){if(!c?.isOrthographicCamera)return;world.compose(c.position,c.quaternion,c.scale??one);view.copy(world).invert();uniforms.uViewProjection.value.multiplyMatrices(c.projectionMatrix,view);uniforms.uEye.value.copy(c.position);forward.set(0,0,-1).applyQuaternion(c.quaternion);const horizontal=Math.hypot(forward.x,forward.z);if(horizontal>.01){const length=(c.far-forward.y*(y-c.position.y))/horizontal;point.set(c.position.x+forward.x/horizontal*length,y,c.position.z+forward.z/horizontal*length).applyMatrix4(uniforms.uViewProjection.value);uniforms.uHorizon.value=THREE.MathUtils.clamp((point.y+1)/2,-.3,1.2);}else uniforms.uHorizon.value=1.2;const h=uniforms.uHorizon.value,space=Math.max(.10,1-h);uniforms.uSunUV.value.set(phase==='night'?.30:.69,h+space*(phase==='evening'?.22:.56));const next=Math.max(30,(c.right-c.left)/Math.max(.001,c.zoom)*1.65);if(Math.abs(next-width)>.001){width=next;waterExtent();}}
 const prepare=(renderer,_scene,c)=>{if(renderer?.getDrawingBufferSize)renderer.getDrawingBufferSize(uniforms.uResolution.value);uniforms.uDetail.value=renderer?.shadowMap?.enabled===false&&renderer?.getPixelRatio?.()<=1.05?0:1;cameraFrame(c??sourceCamera);};for(const o of[sky,water,boat])o.onBeforeRender=prepare;
 tint();waterExtent();poseBoat();cameraFrame(sourceCamera);
 return {root,update(dt,{reduced=false,paused=false,camera:nextCamera,centerX:nextX,coastZ:nextCoast,waterY:nextY,mood:nextMood,waterColor:nextColor}={}){if(!alive)return;if(nextCamera?.isOrthographicCamera)sourceCamera=nextCamera;const nx=safe(nextX,x),nc=safe(nextCoast,coast),ny=safe(nextY,y),changed=nx!==x||nc!==coast||ny!==y;x=nx;coast=nc;y=ny;if(PALETTES[nextMood])phase=nextMood;else if(nextColor?.isColor&&[nextColor.r,nextColor.g,nextColor.b].every(Number.isFinite))phase=nearestMood(nextColor);tint();if(!reduced&&!paused&&Number.isFinite(dt)&&dt>0)time=(time+Math.min(.1,dt))%(Math.PI*8000);uniforms.uTime.value=time;if(changed)waterExtent();poseBoat();cameraFrame(sourceCamera);},snapshot(){const triangles=(boat.geometry.index?.count??boat.geometry.attributes.position.count)/3+4,vertices=boat.geometry.attributes.position.count+8;return{alive,time,mood:phase,triangles:alive?triangles:0,vertices:alive?vertices:0,drawCalls:alive?3:0,meshes:alive?3:0,geometries:alive?3:0,materials:alive?3:0,textures:0,renderTargets:0,cloudOctaves:uniforms.uDetail.value>.5?3:2,boat:{x:boat.position.x,y:boat.position.y,z:boat.position.z,roll:boat.rotation.z},drawingBuffer:uniforms.uResolution.value.toArray(),maximumNewFullScreenPasses:2};},dispose(){if(!alive)return;alive=false;for(const o of[sky,water,boat]){o.geometry.dispose();o.material.dispose();o.onBeforeRender=()=>{};}root.removeFromParent();root.clear();sourceCamera=null;}};
}
